+import AppKit
+import ApplicationServices
+
+func axValue(_ element: AXUIElement, _ attribute: CFString) -> AnyObject? {
+    var value: CFTypeRef?
+    let err = AXUIElementCopyAttributeValue(element, attribute, &value)
+    return err == .success ? (value as AnyObject?) : nil
+}
+
+func axString(_ element: AXUIElement, _ attribute: CFString) -> String? {
+    axValue(element, attribute) as? String
+}
+
+func axFrame(_ element: AXUIElement) -> CGRect? {
+    var value: CFTypeRef?
+    guard AXUIElementCopyAttributeValue(element, "AXFrame" as CFString, &value) == .success,
+          let axValue = value else { return nil }
+    var rect = CGRect.zero
+    guard AXValueGetValue(axValue as! AXValue, .cgRect, &rect) else { return nil }
+    return rect
+}
+
+func walk(_ element: AXUIElement, depth: Int = 0, maxDepth: Int = 5) {
+    let role = axString(element, kAXRoleAttribute as CFString) ?? "?"
+    let title = axString(element, kAXTitleAttribute as CFString)
+    let label = axString(element, kAXDescriptionAttribute as CFString)
+    if role == kAXButtonRole as String || role == kAXStaticTextRole as String {
+        if let title, !title.isEmpty || label != nil {
+            let frame = axFrame(element).map { "\($0.origin.x),\($0.origin.y),\($0.size.width),\($0.size.height)" } ?? "-"
+            print(String(repeating: "  ", count: depth) + "role=\(role) title=\(title ?? "-") desc=\(label ?? "-") frame=\(frame)")
+        }
+    }
+    guard depth < maxDepth, let children = axValue(element, kAXChildrenAttribute as CFString) as? [AXUIElement] else { return }
+    for child in children { walk(child, depth: depth + 1, maxDepth: maxDepth) }
+}
+
+guard let simulator = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.iphonesimulator").first else {
+    fputs("No Simulator app found\n", stderr)
+    exit(1)
+}
+
+let appEl = AXUIElementCreateApplication(simulator.processIdentifier)
+walk(appEl)

